import{_ as s,l,o as e,c as n,v as t,p as o,x as i,d as E,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"EEVDF","description":"","frontmatter":{"title":"EEVDF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/eevdf.md","filePath":"cs/eevdf.md","lastUpdated":1789023840000}'),h={name:"cs/eevdf.md"};function p(m,a,u,f,_,F){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="eevdf" tabindex="-1">EEVDF <a class="header-anchor" href="#eevdf" aria-label="Permalink to &quot;EEVDF&quot;">​</a></h1><div class="epigraph"><p>EEVDF 用合格时延选出「最该跑」的任务：虚拟时间仍在，但决策看的是谁最落后于自己的截止，而不只是最小 vruntime。</p><footer>—— 据 Stoica and Abdel-Wahab, EEVDF；Linux CFS 之后对 EEVDF 的合并说明；[vruntime](/cs/cfs-vruntime) 为先修</footer></div><p><a href="/cs/asan-mechanism">上一课</a>收口内存工具。调度主干停在 <a href="/cs/cfs-vruntime">CFS vruntime</a>。Linux 用 <strong>EEVDF</strong> 换掉「总跑最饿的」在延迟上的钝感。缺口是合格时延，不是再定义公平份额。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CFS 选最小 vruntime，交互任务仍可能排在长 CPU 作业后面等到一个时间片。EEVDF：每个任务有请求的延迟参数，算出虚拟截止时间，选「已合格且截止最早」者。缺口：与 nice 权重如何同时成立；sleep 醒来如何放置以免作弊。本课不把补丁里的每个启发式写成 changelog。</p><p><span class="marginnote">「合格」意味着虚拟时间已到该任务该得的份额。latency nice 是用户旋钮。对象仍是公平类，不是 FIFO 实时。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记账：跑则推进虚拟时间。选择：在合格集合里取最早截止。对照 CFS 红黑树：树键从 vruntime 换成 deadline。对照 <a href="/cs/blk-schedulers">blk BFQ</a>：都是份额+延迟，介质一个 CPU 一个块设备。对照 <a href="/cs/socket-buffers">套接字</a>：与网络无关。</p>',8)),(e(),o(d,null,{default:i(()=>[c(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20RUN%5B%22%E5%AE%9E%E9%99%85%E8%BF%90%E8%A1%8C%22%5D%20--%3E%20VT%5B%22%E6%8E%A8%E8%BF%9B%E8%99%9A%E6%8B%9F%E6%97%B6%E9%97%B4%22%5D%0A%20%20VT%20--%3E%20ELIG%5B%22%E5%90%88%E6%A0%BC%E9%9B%86%E5%90%88%22%5D%0A%20%20ELIG%20--%3E%20EDD%5B%22%E6%9C%80%E6%97%A9%E8%99%9A%E6%8B%9F%E6%88%AA%E6%AD%A2%22%5D%0A%20%20EDD%20--%3E%20CPU%5B%22%E4%B8%8A%20CPU%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>EEVDF 把「公平」从「追平已吃时间」细化成「尊重延迟请求的公平」，使桌面与容器尾延迟更好，而不回到固定优先级。不要写成实时 EDF 保证——过载时仍是尽力。与 <a href="/cs/memcg">memcg</a> 无关直接，但回收会让任务睡眠，虚拟时间规则仍适用。</p><p>默认参数必须保守，否则每个任务都要低延迟会退化成 CFS。</p><p>实现上：latency-nice 让任务要更早的截止，但权重仍约束份额，否则人人最低延迟。实现用红黑树或类似结构按 deadline 排序。过载时合格集合变大，行为接近 CFS。 读法上只引用<a href="/cs/asan-mechanism">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>EEVDF</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证某主线版本字段名。不引入 SCHED_FIFO 的优先级。下一课多核：调度域与拓扑。</p><p>版本字段会变，课序钉的是机制对象「EEVDF」，不是某一主线内核的结构体名。 后课默认：公平类可用合格时延选任务。CPU 拓扑如何限制迁移，下一课调度域。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EEVDF 在合格任务中选最早截止。</li><li>仍是公平份额，不是硬实时。</li><li>调度域是下一课。</li><li>出处：Stoica EEVDF；Linux scheduler；CFS 先修。</li></ul>',11))])}const V=s(h,[["render",p]]);export{A as __pageData,V as default};
